catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
   if (isLoading || newValue === '') {
      return;
   }
   g_form.setDisplay('vpn_region',false);
   g_form.setDisplay('source_ip',false);
   g_form.setDisplay('destination_ip',false);
   g_form.setDisplay('port_number', false);
    g_form.setDisplay('location', false);
    g_form.setDisplay('building', false);
   //Type appropriate comment here, and begin script below
   if(newValue=='vpn_access'){
    g_form.setDisplay('vpn_access',true);
   }
    if (newValue == 'firewall_change') {
        g_form.setDisplay('source_ip', true);
        g_form.setDisplay('destination_ip', true);
        g_form.setDisplay('port_number', true);
    }
    if (newValue == 'wi_fi_access') {
        g_form.setDisplay('location', true);
        g_form.setDisplay('building', true);
    }

}
